"""Ascend ``nonzero`` / ``nonzero_numpy``.

The generic (per-element scatter) formulation is very slow on Ascend: writing
one ``int64`` pair per non-zero element lowers to scalar stores (~7 ns each).
This implementation streams the input in tiles and turns the output write into
a *contiguous* one:

1. ``_nonzero_count_kernel``  -- count the non-zeros of every tile.
2. ``_nonzero_scan_kernel``   -- exclusive prefix sum of those counts, i.e. the
   output row base of every tile (the total lands in ``bases[num_tiles]``).
3. ``_nonzero_write_kernel``  -- compact each tile in-block (one ``vsort`` on
   unique keys gathers the non-zeros into the tile's first ``cnt`` slots) and
   write ``cnt`` coordinate pairs with a single affine store.

Keeping the tile's compaction in-block preserves torch's row-major ordering
without any atomics or host round-trip.

Two Ascend codegen pitfalls are worked around here:

* a boolean ``&`` of a vector with a load mask, and ``tl.interleave`` of a
  boolean mask, take a slow path (the latter silently drops writes), so masks
  are plain comparisons on a fresh ``tl.arange``;
* adding a scalar *derived from* ``program_id`` to a vector produced by a sort
  makes the following store scalarise (~14x slower), while adding a scalar
  *loaded from memory* is free -- hence the per-tile scalars are loaded from
  ``bases`` / ``starts`` instead of being recomputed.
"""

import logging

import torch
import triton
import triton.language as tl
from triton.language.extra.cann import extension as _al

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry
from flag_gems.utils import triton_lang_extension as ext

_MAX_GRID_X = 65535  # device grid-dimension limit (Ascend coreDim <= 65535)

# Elements handled by one tile.  The tile size also bounds the in-tile sort
# used by the 2-D fast path (``hivm.hir.vsort`` only supports 16/32-bit floats
# and stays inside the 196 KB UB budget up to 1024 elements).
_TILE = 1024
# Chunk size of the single-program prefix scan over the per-tile counts.
_SCAN_BLOCK = 4096

logger = logging.getLogger(__name__)


@libentry()
@triton.jit
def _nonzero_count_kernel(inp, counts, n_elements, num_tiles, TILE: tl.constexpr):
    """Count the non-zero elements of every tile."""
    pid = ext.program_id(0)
    n_prog = ext.num_programs(0)
    i = tl.arange(0, TILE)
    tasks = tl.cdiv(num_tiles - pid, n_prog)
    for k in range(tasks):
        tile = pid + k * n_prog
        offs = tile * TILE + i
        vals = tl.load(inp + offs, mask=offs < n_elements, other=0)
        # ``other=0`` already excludes masked-out lanes; ANDing the mask into
        # the comparison would take a very slow path on Ascend.
        cnt = tl.sum((vals != 0).to(tl.int32), axis=0)
        tl.store(counts + tile, cnt)


@libentry()
@triton.jit
def _nonzero_scan_kernel(
    counts, starts, bases, num_tiles, TILE: tl.constexpr, BLOCK: tl.constexpr
):
    """Exclusive prefix sum of the per-tile counts; total in ``bases[-1]``.

    The per-tile flat start is materialised here as well: the write kernel
    needs it as an opaque (loaded) scalar, see the module docstring.
    """
    off = tl.arange(0, BLOCK)
    running = tl.zeros((), dtype=tl.int32)
    n_chunks = tl.cdiv(num_tiles, BLOCK)
    for c in range(n_chunks):
        idx = c * BLOCK + off
        mask = idx < num_tiles
        cnt = tl.load(counts + idx, mask=mask, other=0)
        excl = tl.cumsum(cnt, 0) - cnt + running
        tl.store(bases + idx, excl, mask=mask)
        tl.store(starts + idx, idx * TILE, mask=mask)
        running += tl.sum(cnt, axis=0)
    tl.store(bases + num_tiles, running)


@libentry()
@triton.jit
def _nonzero_write2d_kernel(
    inp,
    bases,
    starts,
    out0,
    out1,
    n_elements,
    num_tiles,
    LOG2_N: tl.constexpr,
    SPLIT: tl.constexpr,
    TILE: tl.constexpr,
):
    """2-D fast path (row length is a power of two).

    ``SPLIT`` writes the two coordinates into two contiguous vectors (that is
    what ``nonzero_numpy`` returns), otherwise they are interleaved into one
    contiguous ``(N, 2)`` buffer like ``torch.nonzero``.
    """
    pid = ext.program_id(0)
    n_prog = ext.num_programs(0)
    i = tl.arange(0, TILE)
    flat_off = tl.arange(0, 2 * TILE)
    N: tl.constexpr = 1 << LOG2_N
    tasks = tl.cdiv(num_tiles - pid, n_prog)
    for k in range(tasks):
        tile = pid + k * n_prog
        start = tl.load(starts + tile)
        base = tl.load(bases + tile)
        offs = start + i
        vals = tl.load(inp + offs, mask=offs < n_elements, other=0)
        flags = vals != 0
        cnt = tl.sum(flags.to(tl.int32), axis=0)
        # Unique keys in [0, 2*TILE): non-zeros keep their in-tile index and
        # zeros sort behind every non-zero.
        key = tl.where(flags, i, TILE + i).to(tl.float32)
        idx = start + _al.sort(key, dim=-1).to(tl.int32)
        if SPLIT:
            tl.store(out0 + base + i, (idx >> LOG2_N).to(tl.int64), mask=i < cnt)
            tl.store(out1 + base + i, (idx & (N - 1)).to(tl.int64), mask=i < cnt)
        else:
            pair = tl.interleave(idx >> LOG2_N, idx & (N - 1)).to(tl.int64)
            tl.store(out0 + base * 2 + flat_off, pair, mask=flat_off < cnt * 2)


@libentry()
@triton.jit
def _nonzero_write_generic_kernel(
    inp,
    bases,
    shape,
    out,
    n_elements,
    num_tiles,
    ndim: tl.constexpr,
    TILE: tl.constexpr,
):
    """Generic path: in-tile cumsum rank + flat index decomposition."""
    pid = ext.program_id(0)
    n_prog = ext.num_programs(0)
    i = tl.arange(0, TILE)
    tasks = tl.cdiv(num_tiles - pid, n_prog)
    for k in range(tasks):
        tile = pid + k * n_prog
        offs = tile * TILE + i
        vals = tl.load(inp + offs, mask=offs < n_elements, other=0)
        flags = vals != 0
        base = tl.load(bases + tile)
        rank = tl.cumsum(flags.to(tl.int32), 0) - 1
        g = base + rank
        idx_flat = offs
        if ndim == 1:
            tl.store(out + g, offs.to(tl.int64), mask=flags)
        else:
            for dim in range(ndim - 1, -1, -1):
                dim_size = tl.load(shape + dim)
                remainder = idx_flat % dim_size
                idx_flat //= dim_size
                tl.store(out + g * ndim + dim, remainder.to(tl.int64), mask=flags)


def _is_pow2(value):
    return value > 0 and (value & (value - 1)) == 0


def _scan_block(num_tiles):
    """Chunk width of the single-program scan; one chunk when it fits."""
    return max(64, min(_SCAN_BLOCK, triton.next_power_of_2(num_tiles)))


def _nonzero_impl(inp, *, as_tuple=False, split=False):
    logger.debug("GEMS NONZERO")

    inp = inp.contiguous()
    ndim = inp.ndim
    n_elements = inp.numel()
    device = inp.device

    if n_elements == 0:
        out = torch.empty((0, ndim), dtype=torch.int64, device=device)
        return tuple(out.unbind(dim=1)) if as_tuple else out

    num_tiles = triton.cdiv(n_elements, _TILE)
    counts = torch.empty(num_tiles, dtype=torch.int32, device=device)
    starts = torch.empty(num_tiles, dtype=torch.int32, device=device)
    bases = torch.empty(num_tiles + 1, dtype=torch.int32, device=device)

    grid = (min(num_tiles, _MAX_GRID_X),)
    # ``split`` only makes sense for rank-2 inputs with a power-of-two row
    # length; it is what ``nonzero_numpy`` wants (two contiguous vectors).
    fast2d = ndim == 2 and _is_pow2(inp.shape[1])
    split = split and fast2d

    if split:
        out0 = torch.empty(n_elements, dtype=torch.int64, device=device)
        out1 = torch.empty(n_elements, dtype=torch.int64, device=device)
    else:
        out0 = torch.empty((n_elements, ndim), dtype=torch.int64, device=device)
        out1 = out0

    with torch_device_fn.device(device):
        _nonzero_count_kernel.run(
            inp,
            counts,
            n_elements,
            num_tiles,
            TILE=_TILE,
            grid=grid,
            warmup=False,
        )
        _nonzero_scan_kernel.run(
            counts,
            starts,
            bases,
            num_tiles,
            TILE=_TILE,
            BLOCK=_scan_block(num_tiles),
            grid=(1,),
            warmup=False,
        )
        if fast2d:
            _nonzero_write2d_kernel.run(
                inp,
                bases,
                starts,
                out0,
                out1,
                n_elements,
                num_tiles,
                LOG2_N=inp.shape[1].bit_length() - 1,
                SPLIT=split,
                TILE=_TILE,
                grid=grid,
                warmup=False,
            )
        else:
            shape = torch.tensor(inp.shape, dtype=torch.int32, device=device)
            _nonzero_write_generic_kernel.run(
                inp,
                bases,
                shape,
                out0,
                n_elements,
                num_tiles,
                ndim=ndim,
                TILE=_TILE,
                grid=grid,
                warmup=False,
            )

    # Single host synchronisation for the whole launch chain.
    total = int(bases[num_tiles].item())

    if split:
        return out0[:total], out1[:total]
    out = out0[:total]
    if as_tuple:
        return tuple(out.unbind(dim=1))
    return out


def nonzero(inp, *, as_tuple=False):
    return _nonzero_impl(inp, as_tuple=as_tuple)
